"""The 2026-11-14 OpenAlex rename: relationships became link types.

`parent_works[].relationship` and the `/links` `relationship` field are now
`link_type`; OpenAlex stops serving the old names on 2026-12-07. The models
accept either while both shapes exist in the wild.
"""

from aletheca import Link
from aletheca.models import RelatedWork


def test_related_work_reads_link_type():
    parent = RelatedWork.model_validate(
        {
            "id": "https://openalex.org/W3109397498",
            "display_name": "Routledge Handbook",
            "link_type": "volume",
        }
    )
    assert parent.link_type == "volume"


def test_related_work_falls_back_to_relationship():
    parent = RelatedWork.model_validate(
        {
            "id": "https://openalex.org/W3109397498",
            "display_name": "Routledge Handbook",
            "relationship": "data-series",
        }
    )
    assert parent.link_type == "data-series"


def test_link_reads_link_type_id():
    edge = Link.model_validate(
        {
            "origin": "https://openalex.org/W2194775991",
            "target": "https://openalex.org/W2102605133",
            "link_type": "https://openalex.org/link-types/citation",
        }
    )
    assert edge.link_type == "https://openalex.org/link-types/citation"


def test_link_maps_old_relationship_ids_to_link_types():
    edge = Link.model_validate(
        {
            "origin": "https://openalex.org/W2194775991",
            "target": "https://openalex.org/W2102605133",
            "relationship": "https://openalex.org/relationships/citation",
        }
    )
    assert edge.link_type == "https://openalex.org/link-types/citation"


def test_link_prefers_link_type_when_both_are_served():
    edge = Link.model_validate(
        {
            "origin": "https://openalex.org/W2194775991",
            "target": "https://openalex.org/W2102605133",
            "relationship": "https://openalex.org/relationships/citation",
            "link_type": "https://openalex.org/link-types/citation",
        }
    )
    assert edge.link_type == "https://openalex.org/link-types/citation"
